		/** 
		 * Tests creating a new Plant.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Plant");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Plant" );

			try {            
				Plant entity = PlantService.getPlantInstance().createPlant( generateNewEntity() );
				thePrimaryKey = entity.getPlantId();
				LOGGER.info( "-- Successfully created a Plant with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Plant. 
		 */
		public Plant testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Plant" );

			Plant entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Plant with primary key" );
			msg.append( thePrimaryKey );
			
			PlantFetchOneSummary fetchOneSummary = new PlantFetchOneSummary( thePrimaryKey );

			try {
				entity = PlantService.getPlantInstance().getPlant( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Plant " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Plant.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Plant." );

			StringBuilder msg = new StringBuilder( "Failed to update a Plant : " );        
			Plant entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Plant." );

				// for use later on...
				thePrimaryKey = entity.getPlantId();

				PlantService proxy = PlantService.getPlantInstance();            
				proxy.updatePlant( entity );   

				LOGGER.info( "-- Successfully saved Plant - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Plant.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Plant." );

			try{
			    Plant entity = testRead(); 
				PlantService.getPlantInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Plant with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Plant with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Plants.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Plants:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Plant : " );        
			List<Plant> collection  = null;

			try {
				// call the static get method on the PlantService
				collection = PlantService.getPlantInstance().getAllPlant();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Plant entity = null;            
					Iterator<Plant> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getPlantId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/**
		 * Assigns a common log handler for each test class in the suite
		 * @param		handler	Handler
		 * @return		PlantTest
		 */
		public PlantTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated Plant
		 * 
		 * @return Plant
		 */
		protected Plant generateNewEntity() {
			Plant entity = new Plant( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new Address(),  null,  new HashSet<>(),  new HashSet<>() );
			
			return( entity );
		}

